import{c as a,Q as l,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Fill","description":"","frontmatter":{},"headers":[{"level":1,"title":"Fill","slug":"fill"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/张量变换/Fill-97.md","filePath":"api/SIMD-API/高阶API/张量变换/Fill-97.md"}'),n={name:"api/SIMD-API/高阶API/张量变换/Fill-97.md"};function i(p,t,d,o,r,c){return l(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="fill" tabindex="-1">Fill <a class="header-anchor" href="#fill" aria-label="Permalink to &quot;Fill&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将Global Memory上的数据初始化为指定值。该接口可用于对workspace地址或输出数据进行清零。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Fill(GlobalTensor&lt;T&gt;&amp; gmWorkspaceAddr, const uint64_t size, const T value)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。不同型号支持的数据类型请参考支持的数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>gmWorkspaceAddr</td><td>输入</td><td>gmWorkspaceAddr为用户定义的全局Global空间，是需要被初始化的空间，类型为GlobalTensor。GlobalTensor数据结构的定义请参考GlobalTensor。</td></tr><tr><td>size</td><td>输入</td><td>需要初始化的空间大小，单位为元素个数。</td></tr><tr><td>value</td><td>输入</td><td>初始化的值，数据类型与gmWorkspaceAddr保持一致。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>单核调用此接口时，如果后续操作涉及Unified Buffer的使用，则需要在调用接口后，设置MTE2流水等待MTE3流水（<a href="./../../基础API/同步控制/核内同步/SetFlag-WaitFlag(ISASI).html#section622mcpsimp">MTE3_MTE2</a>）的同步。</p></li><li><p>单核上连续多次调用此接口且初始化的值不一致时，需要在接口之间设置V流水等待MTE3流水（<a href="./../../基础API/同步控制/核内同步/SetFlag-WaitFlag(ISASI).html#section622mcpsimp">MTE3_V</a>）的同步。由于该接口内部使用同一块Unified Buffer作为中转空间进行值初始化，连续调用接口时若不进行流水同步，后一次写操作可能覆盖前一次未完成写入的数据，导致前一次初始化Global Memory的结果非预期。</p></li><li><p>当多个核调用此接口对Global Memory进行初始化时，所有核对Global Memory的初始化未必会同时结束，也可能存在核之间读后写、写后读以及写后写等数据依赖问题。这种使用场景下，可以在本接口后调用<a href="./../../基础API/同步控制/核间同步/SyncAll.html">SyncAll</a>接口保证多核间同步正确。</p></li><li><p>该接口仅支持在程序内存分配<a href="./../../基础API/资源管理/Pipe和Que框架/TPipe/InitBuffer.html">InitBuffer</a>接口前使用。</p></li><li><p>支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t、int8_t、uint16_t、int16_t、bfloat16_t、half、uint32_t、int32_t、float、uint64_t、int64_t。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：uint16_t、int16_t、half、uint32_t、int32_t、float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：uint16_t、int16_t、half、uint32_t、int32_t、float。</p><p>Atlas 推理系列产品AI Core，支持的数据类型为：uint16_t、int16_t、half、uint32_t、int32_t、float。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本调用示例使用8个核，每个核用当前blockIdx的值初始化zGm上的65536个数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 带初始化的元素个数</span></span>
<span class="line"><span>constexpr int32_t INIT_SIZE = 65536;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 设置源操作数在Global Memory上的起始地址为z+INIT_SIZE*blockIdx，所占外部存储的大小为INIT_SIZE个float</span></span>
<span class="line"><span>zGm.SetGlobalBuffer((__gm__ float*)z + INIT_SIZE * AscendC::GetBlockIdx(), INIT_SIZE);</span></span>
<span class="line"><span>// 将起始地址为z+INIT_SIZE*blockIdx和大小为INIT_SIZE个float源操作数zGm的值，初始化为每个核用当前blockIdx</span></span>
<span class="line"><span>AscendC::Fill(zGm, INIT_SIZE, (float)(AscendC::GetBlockIdx()));</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始化后zGm数据：</span></span>
<span class="line"><span>[0. 0. 0. ... 0. 0. 0.</span></span>
<span class="line"><span> 1. 1. 1. ... 1. 1. 1.</span></span>
<span class="line"><span> 2. 2. 2. ... 2. 2. 2.</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> 5. 5. 5. ... 5. 5. 5.</span></span>
<span class="line"><span> 6. 6. 6. ... 6. 6. 6.</span></span>
<span class="line"><span> 7. 7. 7. ... 7. 7. 7.]</span></span></code></pre></div>`,21)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
